  function tableRows(data) { const rows=data?.rows||[]; if(!rows.length) return empty('Nenhuma inscrição encontrada','As inscrições aparecerão aqui conforme forem realizadas.'); return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Participante</th><th>Inscrição</th><th>Categoria</th><th>Situação</th><th>Tipo</th><th>Pagamento</th><th>Kit</th><th>Check-in</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.cpf_masked)}</small></td><td>#${esc(r.number)}</td><td>${esc(r.category_name)}</td><td>${badge(r.status)}</td><td>${badge(r.type)}</td><td>${badge(r.payment_status)}</td><td>${r.kit_at?'Retirado':'Pendente'}</td><td>${r.checkin_at?'Realizado':'Pendente'}</td><td><button class="icon-button" data-registration="${esc(r.id)}" title="Visualizar inscrição">${icon('eye',18)}</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${data.total||rows.length} registro(s)</span></div>`; }
  function resources(kind) { const cat=kind==='categorias'||kind==='categories'; return `${heading(cat?'Categorias':'Lotes e valores','CONFIGURAÇÃO DO EVENTO',cat?'Percursos, critérios e capacidade por categoria.':'Disponibilidade e valores definidos por lote.',member&&['SUPER_ADMIN','ADMIN'].includes(member.role)?`<button class="primary-button compact" data-create-resource>${icon('plus',18)}${cat?'Nova categoria':'Novo lote'}</button>`:'')}<div id="resources-data">${loading()}</div>`; }
