  function invitationRows(rows) { if(!rows?.length)return empty('Nenhum convite gerado','Crie um convite para liberar uma inscrição de Colaborador MPL.');const labels={DISPONIVEL:'Disponível',UTILIZADO:'Utilizado',EXPIRADO:'Expirado',CANCELADO:'Cancelado'};return `<div class="table-scroll"><table class="data-table invitation-table"><thead><tr><th>Corrida / categoria</th><th>Link</th><th>Status</th><th>Criação</th><th>Utilização</th><th>Colaborador</th><th>Ações</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.event_name)}</strong><small>${esc(r.category_name)} · ${esc(r.distancia_km)} km</small></td><td><input class="invitation-link" value="${esc(r.link)}" readonly></td><td>${badge(r.status)}</td><td>${dateTime(r.criado_em)}</td><td>${r.utilizado_em?dateTime(r.utilizado_em):'—'}</td><td>${r.collaborator_name?`<strong>${esc(r.collaborator_name)}</strong><small>${esc(r.collaborator_email)}</small>`:'—'}</td><td><div class="table-actions">${r.status==='DISPONIVEL'?`<button data-copy-invite="${esc(r.id)}">Copiar</button><button data-send-invite="${esc(r.id)}">Enviar</button><button class="danger-link" data-cancel-invite="${esc(r.id)}">Cancelar</button>`:''}${r.status==='UTILIZADO'?`<button data-resend-invite="${esc(r.id)}">Reenviar confirmação</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`; }
  function openInvitation(options, reload) { const events=[...new Map((options||[]).map(x=>[String(x.event_id),x])).values()];const m=showModal('Gerar convite de Colaborador MPL',`<form id="invitation-form"><div class="form-field"><label>Corrida</label><select name="event_id" required><option value="">Selecione</option>${events.map(x=>`<option value="${esc(x.event_id)}">${esc(x.event_name)} · 5 km</option>`).join('')}</select></div><div class="notice">${icon('route',18)}<div>O convite será válido exclusivamente para a prova de 5 km.</div></div><button class="primary-button">Gerar link único</button><div id="invitation-form-message"></div></form>`);const f=m.querySelector('form');f.onsubmit=async e=>{e.preventDefault();try{await loadAdmin('create-invitation',{event_id:f.event_id.value});m.querySelector('#invitation-form-message').innerHTML=alert('Convite criado. O link já está disponível para copiar.');setTimeout(()=>{m.remove();reload();},500);}catch(err){m.querySelector('#invitation-form-message').innerHTML=alert(err.message,'error');}}; }
  function sponsorRows(data) { if(!data?.length) return empty('Nenhuma solicitação de patrocínio','As empresas interessadas aparecerão aqui.'); return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Empresa</th><th>Contato</th><th>Recebida em</th><th>Status</th><th>Publicação</th><th></th></tr></thead><tbody>${data.map(r=>`<tr><td><strong>${esc(r.company)}</strong><small>${esc(r.email)}</small></td><td>${esc(r.contact_name)}<small>${esc(r.phone)}</small></td><td>${dateTime(r.created_at)}</td><td>${badge(r.status)}</td><td>${r.published?'Visível':'Não publicada'}</td><td><button class="icon-button" data-edit-sponsor='${esc(JSON.stringify(r))}'>${icon('eye',18)}</button></td></tr>`).join('')}</tbody></table></div>`; }
  async function uploadSponsorLogo(id,file) { const fd=new FormData(); fd.append('sponsor_id',id); fd.append('logo',file); const token=sessionStorage.getItem('mpl_token'); const res=await fetch(`${C.api_base||`${BASE}/api.php`}?action=sponsor-logo-upload`,{method:'POST',headers:token?{Authorization:`Bearer ${token}`,'X-MPL-Token':token}:{},body:fd}); const data=await res.json().catch(()=>({error:'Resposta inválida'})); if(!res.ok||data?.error) throw new Error(data.error||'Logo não enviada.'); return data; }
  function openSponsor(record) { const m=showModal('Analisar solicitação',`<form id="sponsor-admin-form"><div class="detail-heading"><h3>${esc(record.company)}</h3>${badge(record.status)}</div><dl class="detail-grid"><div><dt>Responsável</dt><dd>${esc(record.contact_name)}</dd></div><div><dt>Contato</dt><dd>${esc(record.email)}<br>${esc(record.phone)}</dd></div><div><dt>Interesse</dt><dd>${record.support_type==='PRODUTOS'?'Produtos que agreguem valor':'Contribuição de R$ 2.500 por edição'}</dd></div><div><dt>Mensagem</dt><dd>${esc(record.message||'Não informada')}</dd></div></dl><div class="form-field"><label>Status</label><select name="status"><option value="PENDENTE">Pendente</option><option value="EM_ANALISE">Em análise</option><option value="APROVADO">Aprovado</option><option value="RECUSADO">Recusado</option></select></div><div class="form-field"><label>Observações internas</label><textarea name="admin_notes" rows="4">${esc(record.admin_notes||'')}</textarea></div><div class="form-field"><label>Logo</label><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></div><label class="checkbox-label"><input type="checkbox" name="published" ${record.published?'checked':''}> Publicar no site</label><button class="primary-button">Salvar análise</button><div id="sponsor-admin-message"></div></form>`); const f=m.querySelector('form');f.status.value=record.status;f.onsubmit=async e=>{e.preventDefault();const data={status:f.status.value,admin_notes:f.admin_notes.value,published:f.published.checked};try{await loadAdmin('update-sponsor',{id:record.id,data});if(f.logo.files[0])await uploadSponsorLogo(record.id,f.logo.files[0]);m.remove();navigate('/admin/patrocinadores');}catch(err){m.querySelector('#sponsor-admin-message').innerHTML=alert(err.message,'error');}}; }
  function settings() { return `${heading('Configurações do evento','ADMINISTRAÇÃO','Informações oficiais, períodos e regulamento.')}<div id="settings-data">${loading()}</div>`; }
  function settingsForm(data={}) { const keys=[['name','Nome do evento','text'],['event_date','Data da corrida','date'],['start_time','Horário da largada','time'],['location','Local da largada','text'],['city','Cidade','text'],['kit_location','Local de retirada do kit','text']]; const dates=[['registration_starts_at','Início das inscrições'],['registration_ends_at','Fim das inscrições'],['kit_starts_at','Início da retirada'],['kit_ends_at','Fim da retirada'],['checkin_starts_at','Início do check-in'],['checkin_ends_at','Fim do check-in'],['ticket_expires_at','Validade dos ingressos']]; return `<form id="settings-form"><fieldset ${['SUPER_ADMIN','ADMIN'].includes(member?.role)?'':'disabled'}><section class="form-section"><div class="form-section-title">${icon('settings')}<h2>Informações do evento</h2></div><div class="form-grid">${keys.map(k=>`<div class="form-field"><label>${k[1]}</label><input name="${k[0]}" type="${k[2]}" value="${esc(data[k[0]]||'')}"></div>`).join('')}</div><label class="checkbox-label"><input type="checkbox" name="published" ${data.published?'checked':''}>Publicar informações do evento</label><label class="checkbox-label"><input type="checkbox" name="registration_open" ${data.registration_open?'checked':''}>Abrir inscrições no período configurado</label></section><section class="form-section"><div class="form-section-title">${icon('calendar')}<h2>Períodos de operação</h2></div><div class="form-grid">${dates.map(k=>`<div class="form-field"><label>${k[1]}</label><input name="${k[0]}" type="datetime-local" value="${esc((data[k[0]]||'').slice(0,16))}"></div>`).join('')}</div></section><section class="form-section"><div class="form-section-title">${icon('image')}<h2>Regras e privacidade</h2></div>${[['rules','Regulamento oficial'],['terms','Termos de participação'],['privacy_notice','Aviso de privacidade e contato LGPD']].map(k=>`<div class="form-field"><label>${k[1]}</label><textarea rows="6" name="${k[0]}">${esc(data[k[0]]||'')}</textarea></div>`).join('')}</section><button class="primary-button compact">${icon('check',17)}Salvar configurações</button></fieldset><div id="settings-message"></div></form>`; }
  function users() { return `${heading('Usuários e acessos','SEGURANÇA DO EVENTO','Cada pessoa, com a permissão necessária.',`<button class="primary-button compact" data-create-user>${icon('plus',18)}Adicionar acesso</button>`)}<div id="users-data">${loading()}</div>`; }
  function userRows(data) { if(!data?.length) return empty('Nenhum acesso administrativo'); return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Usuário</th><th>Perfil</th><th>Situação</th><th></th></tr></thead><tbody>${data.map(u=>`<tr><td><strong>${esc(u.email)}</strong></td><td>${esc(u.role)}</td><td>${u.active?'Ativo':'Inativo'}</td><td><button class="icon-button" data-edit-user='${esc(JSON.stringify(u))}'>${icon('edit',17)}</button></td></tr>`).join('')}</tbody></table></div>`; }
  function setView(html) { app.innerHTML=html; window.scrollTo({top:0,behavior:'instant'}); bindCommon(); }
  function bindCommon() { document.querySelectorAll('a[href]').forEach(a=>{ const href=a.getAttribute('href'); if(!href||href.startsWith('#')||href.startsWith('http')||a.target==='_blank') return; a.addEventListener('click',e=>{e.preventDefault(); navigate(href);}); }); document.querySelector('[data-menu]')?.addEventListener('click',()=>document.querySelector('.site-nav')?.classList.toggle('open')); document.querySelector('[data-open-sidebar]')?.addEventListener('click',()=>document.querySelector('.admin-sidebar')?.classList.add('open')); document.querySelector('[data-close-sidebar]')?.addEventListener('click',()=>document.querySelector('.admin-sidebar')?.classList.remove('open')); document.querySelector('[data-logout]')?.addEventListener('click',logout); }
  function showModal(title, body) { const el=document.createElement('div'); el.className='modal-backdrop'; el.innerHTML=`<div class="app-modal"><button class="icon-button modal-close">${icon('close')}</button><h2>${title}</h2><p class="subtle">4ª Corrida MPL</p>${body}</div>`; document.body.appendChild(el); el.querySelector('.modal-close').onclick=()=>el.remove(); return el; }
  function bindEmailForm(root=document) {
    const form=root.querySelector('#email-form'); if(!form) return;
    form.onsubmit=async e=>{
      e.preventDefault(); const email=form.email.value.trim().toLowerCase(); const error=form.querySelector('[data-error="email"]');
      if(!/^\S+@\S+\.\S+$/.test(email)){error.textContent='Informe um e-mail válido.';return;}
      error.textContent=''; const button=form.querySelector('button[type="submit"]'); if(!button)return; button.disabled=true;
      try{
        await invoke('request-participant-access',{email});
        form.innerHTML=`<p>Enviamos um código de 6 dígitos para <strong>${esc(email)}</strong>, caso exista uma inscrição cadastrada.</p><div class="form-field"><label>Código de acesso</label><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required><span class="field-error" data-error="code"></span></div><button class="primary-button" type="submit">Acessar minha inscrição${icon('right',16)}</button><button type="button" class="text-link" data-change-email>Usar outro e-mail</button>`;
        form.querySelector('[data-change-email]').onclick=()=>navigate('/consultar-inscricao');
        form.onsubmit=async ev=>{
          ev.preventDefault(); const code=form.code.value.replace(/\D/g,'');
          if(code.length!==6){form.querySelector('[data-error="code"]').textContent='Informe os 6 dígitos.';return;}
          const verifyButton=form.querySelector('button[type="submit"]'); verifyButton.disabled=true;
          try{const result=await invoke('verify-participant-access',{email,code});sessionStorage.setItem('mpl_participant_token',result.token);sessionStorage.setItem('mpl_participant_email',result.email);session={user:{email:result.email}};navigate('/minha-inscricao');}
          catch(err){form.querySelector('[data-error="code"]').textContent=err.message;verifyButton.disabled=false;}
        };
      }catch(err){form.insertAdjacentHTML('afterend',alert(err.message,'error','email-access-error'));button.disabled=false;}
    };
  }
  function bindRegistration() {
    const form = document.querySelector('#registration-form');
    if (!form) return;
    const submitButton = form.querySelector('button[type="submit"]');
    if (activeInvitation && !activeInvitation.error) {
      form.insertAdjacentHTML('afterbegin', `<input type="hidden" name="invitation_token" value="${esc(new URLSearchParams(location.search).get('convite')||'')}">`);
      document.getElementById('selected-category').textContent = `${esc(activeInvitation.distance_km)} km · Colaborador MPL`;
      document.getElementById('selected-price').textContent = 'Isento';
      if (submitButton) submitButton.disabled = false;
      const closed = form.querySelector('.summary-closed'); if (closed) closed.remove();
    } else if (activeInvitation && activeInvitation.error) {
      document.getElementById('registration-error').innerHTML = alert(activeInvitation.error, 'error');
      if (submitButton) submitButton.disabled = true;
    }
    const emergencyToggle = form.querySelector('[name="has_emergency_contact"]');
    const emergencyFields = form.querySelector('.emergency-fields');
    const updateEmergency = () => {
      const enabled = Boolean(emergencyToggle?.checked);
      emergencyFields.hidden = !enabled;
      emergencyFields.querySelectorAll('input').forEach(input => { input.disabled = !enabled; });
      if (!enabled) emergencyFields.querySelectorAll('[data-error]').forEach(x => { x.textContent = ''; });
    };
    const update = () => {
      form.querySelectorAll('.shirt-options label').forEach(x => x.classList.toggle('selected', x.querySelector('input').checked));
    };
    emergencyToggle?.addEventListener('change', updateEmergency);
    form.addEventListener('change', update);
    updateEmergency();
    update();
    form.addEventListener('submit', async e => {
      e.preventDefault();
      if (pending) return;
      if (!event.registration_open && !activeInvitation) {
        document.getElementById('registration-error').innerHTML = alert('As inscrições ainda não estão abertas.', 'error', 'registration-submit-error');
        return;
      }
      const fd = new FormData(form);
      const values = Object.fromEntries(fd.entries());
      const errs = {};
      ['name','cpf','birth_date','gender','email','phone','shirt_size'].forEach(k => { if (!values[k]) errs[k] = 'Preencha este campo.'; });
      if (emergencyToggle?.checked) ['emergency_name','emergency_phone'].forEach(k => { if (!values[k]) errs[k] = 'Preencha este campo.'; });
      if (values.name && String(values.name).trim().length < 5) errs.name = 'Informe seu nome completo.';
      if (values.cpf && !/^\d{11}$/.test(String(values.cpf).replace(/\D/g, ''))) errs.cpf = 'CPF inválido.';
      if (values.email && !/^\S+@\S+\.\S+$/.test(String(values.email))) errs.email = 'Informe um e-mail válido.';
      if (values.phone && String(values.phone).replace(/\D/g, '').length < 10) errs.phone = 'Informe o celular com DDD.';
      if (emergencyToggle?.checked && values.emergency_phone && String(values.emergency_phone).replace(/\D/g, '').length < 10) errs.emergency_phone = 'Informe o celular com DDD.';
      if (!values.rules_accepted) errs.rules_accepted = 'É necessário aceitar o regulamento.';
      if (!values.lgpd_accepted) errs.lgpd_accepted = 'É necessário aceitar os termos da LGPD.';
      form.querySelectorAll('[data-error]').forEach(x => x.textContent = errs[x.dataset.error] || '');
      if (Object.keys(errs).length) {
        document.getElementById('registration-error').innerHTML = alert('Confira os campos destacados.', 'error', 'registration-submit-error');
        return;
      }
      pending = true;
      if (submitButton) { submitButton.disabled = true; submitButton.dataset.originalText = submitButton.textContent; submitButton.firstChild.textContent = 'Processando inscrição'; }
      try {
        const created = await invoke('create-registration', { ...values, event_id: event.id, cpf: String(values.cpf).replace(/\D/g, '') });
        if(created.participant_token){sessionStorage.setItem('mpl_participant_token',created.participant_token);sessionStorage.setItem('mpl_participant_email',created.participant_email||values.email);session={user:{email:created.participant_email||values.email}};}
        session = { user: { email: String(values.email).trim().toLowerCase() } };
        await navigate(created.is_collaborator ? '/minha-inscricao' : `/pagamento?inscricao=${encodeURIComponent(created.id)}`);
      } catch (err) {
        document.getElementById('registration-error').innerHTML = alert(err.message, 'error', 'registration-submit-error');
        pending = false;
        if (submitButton) { submitButton.disabled = false; submitButton.firstChild.textContent = 'Continuar inscrição'; }
      }
    });
  }
  function bindParticipantEmailActions(registration) {
    const message = document.getElementById('resend-email-message');
    const sendButton = document.querySelector('[data-send-participant-email]');
    const resendButton = document.querySelector('[data-resend-registration-email]');

    if (sendButton && message) sendButton.addEventListener('click', async () => {
      const original = sendButton.innerHTML;
      sendButton.disabled = true;
      sendButton.textContent = 'Enviando ingresso…';
      message.innerHTML = alert('Preparando o ingresso e conectando ao servidor de e-mail.');
      try {
        const result = await invoke('send-participant-email', { registration_id: registration.id });
        message.innerHTML = alert(result.has_qr ? 'Ingresso e QR Code enviados para seu e-mail.' : 'Acesso enviado. O QR Code será liberado após a confirmação do pagamento.');
      } catch (err) {
        message.innerHTML = alert(err.message, 'error');
      } finally {
        sendButton.disabled = false;
        sendButton.innerHTML = original;
      }
    });

    if (resendButton && message) resendButton.addEventListener('click', async () => {
      const original = resendButton.textContent;
      resendButton.disabled = true;
      resendButton.textContent = 'Enviando…';
      message.innerHTML = alert('Enviando os dados da inscrição.');
      try {
        await invoke('resend-registration-email', { registration_id: registration.id });
        message.innerHTML = alert('Dados reenviados com sucesso.');
      } catch (err) {
        message.innerHTML = alert(err.message, 'error');
      } finally {
        resendButton.disabled = false;
        resendButton.textContent = original;
      }
    });
  }

  async function renderParticipantData() {
    const box = document.getElementById('participant-content');
    if (!box) return;
    if (!session) { navigate('/consultar-inscricao'); return; }
    try {
      const r = await invoke('search-registration', { slug: EVENT_SLUG });
      if (!r) { box.innerHTML = empty('Nenhuma inscrição por aqui ainda', action('/inscricao', 'Fazer minha inscrição')); return; }
      let token = '';
      if (r.status === 'CONFIRMED') {
        try { token = (await invoke('generate-ticket', { registration_id: r.id })).token; } catch {}
      }
      box.innerHTML = `<div class="participant-layout"><div><div class="participant-ticket"><div class="ticket-header"><span class="eyebrow">4ª CORRIDA MPL</span>${badge(r.status,'participant-status')}</div><h2>${esc(r.name)}</h2><span class="subtle">Inscrição #${esc(r.number)}</span>${r.type==='COLABORADOR_MPL'?alert('Inscrição gratuita, Colaborador MPL','','participant-free'):''}<dl class="detail-grid"><div><dt>Categoria</dt><dd>${esc(r.category_name)}</dd></div><div><dt>Camiseta</dt><dd>${esc(r.shirt_size)}</dd></div><div><dt>Valor da inscrição</dt><dd>${money(r.amount_cents)}</dd></div><div><dt>Pagamento</dt><dd>${badge(r.payment_status)}</dd></div><div><dt>${icon('shirt',15)}Retirada do kit</dt><dd>${r.kit_at?dateTime(r.kit_at):'Não retirado'}</dd></div><div><dt>${icon('scan',15)}Check-in</dt><dd>${r.checkin_at?dateTime(r.checkin_at):'Não realizado'}</dd></div></dl>${r.status==='PENDING'&&r.type==='PUBLICO'?action('/pagamento','Ir para pagamento'):''}</div><div class="event-reminder">${icon('calendar',27)}<div><strong>${eventDate(event.event_date)}</strong><p>${esc(event.location||'Local a definir')} · ${(event.start_time||'Horário em breve').slice(0,5)}</p></div></div><div class="participant-email-actions"><button type="button" class="action-link outline" data-send-participant-email aria-controls="resend-email-message">Enviar acesso e QR por e-mail${icon('right',15)}</button><button type="button" class="text-link" data-resend-registration-email aria-controls="resend-email-message">Reenviar dados da inscrição</button></div><div id="resend-email-message" aria-live="polite"></div></div><aside class="ticket-panel"><h2>Seu ingresso</h2>${token?`<div class="ticket-qr"><canvas id="ticket-qr-canvas"></canvas><p>Um QR Code. Do kit à largada.</p><button type="button" class="action-link outline" data-download-qr>${icon('download',16)}Salvar QR Code</button><small>Não compartilhe seu ingresso publicamente.</small></div>`:empty('QR Code ainda indisponível',r.status==='CONFIRMED'?'Atualize para tentar emitir novamente.':'O ingresso será liberado após a confirmação da inscrição.')}</aside></div>`;

      // Os botões precisam funcionar mesmo se a biblioteca do QR falhar.
      bindParticipantEmailActions(r);

      if (token && window.QRCode && typeof QRCode.toCanvas === 'function') {
        try {
          const canvas = document.getElementById('ticket-qr-canvas');
          const rendering = QRCode.toCanvas(canvas, token, { width:220, margin:4, errorCorrectionLevel:'M' });
          if (rendering && typeof rendering.catch === 'function') rendering.catch(() => {});
          const downloadButton = document.querySelector('[data-download-qr]');
          if (downloadButton) downloadButton.onclick = () => {
            const a = document.createElement('a');
            a.href = canvas.toDataURL('image/png');
            a.download = 'ingresso-corrida-mpl.png';
            a.click();
          };
        } catch (ignored) {}
      }
    } catch (err) {
      box.innerHTML = alert(err.message, 'error', 'participant-error');
    }
  }
  function paymentStatusText(status, gatewayStatus) {
    const labels = { PENDING_PAYMENT: 'Aguardando início', PROCESSING: 'Aguardando confirmação', PAID: 'Pagamento aprovado', FAILED: 'Pagamento recusado', EXPIRED: 'Pagamento expirado', CANCELLED: 'Pagamento cancelado' };
    return labels[status] || gatewayStatus || 'Aguardando confirmação';
  }
  function paymentSummary(record) {
    return `<div class="payment-summary"><span class="eyebrow">RESUMO DA INSCRIÇÃO</span><h2>${esc(record.name)}</h2><dl class="detail-grid"><div><dt>Inscrição</dt><dd>#${esc(record.number)}</dd></div><div><dt>Categoria</dt><dd>${esc(record.category_name)}</dd></div><div><dt>Distância</dt><dd>${esc(record.distance_km)} km</dd></div><div><dt>Valor</dt><dd>${money(record.amount_cents)}</dd></div></dl></div>`;
  }
  function paymentShell(record) { return `${paymentSummary(record)}<section class="payment-choice checkout-mpl"><div class="checkout-brand"><img src="${BASE}/assets/images/logo/logo-mpl.png" alt="Grupo MPL"><div><span class="eyebrow">CHECKOUT SEGURO</span><h2>Pagamento da inscrição</h2><p>Você continuará no ambiente protegido Pagar.me/Stone. A Corrida MPL não recebe nem armazena os dados do cartão.</p></div></div><div class="checkout-methods"><div>${icon('check',20)}<span><strong>PIX</strong><small>QR Code e copia e cola</small></span></div><div>${icon('check',20)}<span><strong>Cartão de crédito</strong><small>Pagamento no ambiente seguro</small></span></div></div><div id="payment-method-panel"><button class="primary-button checkout-button" data-create-checkout>Ir para pagamento seguro${icon('right',17)}</button><small class="checkout-security">Após a confirmação, o ingresso com QR Code será enviado ao e-mail cadastrado.</small><div id="payment-action-message"></div></div></section>`; }
  function paymentResult(record,payment){if(!payment)return '<p class="subtle">Nenhum Checkout criado.</p>';const status=payment.status||'PROCESSING';if(status==='PAID')return `<div class="payment-success">${icon('check',46)}<h2>Pagamento aprovado.</h2><p>Seu ingresso foi liberado.</p>${action('/minha-inscricao','Ver minha inscrição','outline')}</div>`;if(['FAILED','EXPIRED','CANCELLED'].includes(status))return `${alert(paymentStatusText(status,payment.gateway_status),'error')}<button class="action-link outline" data-payment-retry>Criar novo Checkout</button>`;return `<div class="checkout-waiting"><div class="payment-status-line">${icon('clock',19)}<strong>${esc(paymentStatusText(status,payment.gateway_status))}</strong></div><p>Conclua o pagamento no Checkout Pagar.me.</p>${payment.checkout_url?'<button class="primary-button" data-open-checkout>Continuar no Checkout'+icon('right',17)+'</button>':''}<small>A confirmação é consultada automaticamente.</small></div>`;}
  function openPagarmeCheckout(url,target){const u=new URL(String(url||''));if(u.protocol!=='https:'||!(u.hostname==='pagar.me'||u.hostname.endsWith('.pagar.me')))throw new Error('Endereço de Checkout inválido.');if(target)target.location=u.href;else window.open(u.href,'mpl-pagarme','noopener');}
  function renderPaymentPanel(record,payment){const panel=document.getElementById('payment-method-panel');if(!panel)return;panel.innerHTML=paymentResult(record,payment);panel.querySelector('[data-open-checkout]')?.addEventListener('click',()=>openPagarmeCheckout(payment.checkout_url));panel.querySelector('[data-payment-retry]')?.addEventListener('click',()=>{document.getElementById('payment-content').innerHTML=paymentShell(record);bindCheckout(record);});}
  async function refreshPayment(record){try{const result=await invoke('pagarme-payment-status',{registration_id:record.id});renderPaymentPanel(record,result.payment);if(result.payment?.status==='PAID'||['FAILED','EXPIRED','CANCELLED'].includes(result.payment?.status))clearInterval(paymentPoll);}catch{}}
  function bindCheckout(record){clearInterval(paymentPoll);const panel=document.getElementById('payment-method-panel');panel?.querySelector('[data-create-checkout]')?.addEventListener('click',async e=>{const button=e.currentTarget;const win=window.open('about:blank','mpl-pagarme');button.disabled=true;try{const result=await invoke('create-checkout',{registration_id:record.id});renderPaymentPanel(record,result.payment);openPagarmeCheckout(result.payment.checkout_url,win);paymentPoll=setInterval(()=>refreshPayment(record),7000);}catch(err){if(win)win.close();panel.querySelector('#payment-action-message').innerHTML=alert(err.message,'error');button.disabled=false;}});}
  async function renderPayment() {
    const box = document.getElementById('payment-content');
    if (!box) return;
    clearInterval(paymentPoll);
    if (!session) { navigate('/consultar-inscricao'); return; }
    const registrationId = Number(new URLSearchParams(location.search).get('inscricao') || 0);
    try {
      const record = await invoke('search-registration', { registration_id: registrationId });
      if (!record) { box.innerHTML = alert('Você ainda não tem uma inscrição neste evento.', 'error'); return; }
      if (record.status === 'CONFIRMED' || record.payment_status === 'APPROVED') { box.innerHTML = paymentSummary(record) + '<div class="payment-success">' + icon('check',46) + '<h2>Inscrição confirmada.</h2>' + action('/minha-inscricao', 'Ver minha inscrição', 'outline') + '</div>'; return; }
      box.innerHTML = paymentShell(record);
      bindCheckout(record);
    } catch (err) { box.innerHTML = alert(err.message, 'error', 'payment-error'); }
  }
  async function loadAdmin(action, params={}) { return await invoke('admin-api',{action,event_id:member?.event_id,...params}); }
  async function bindAdminPage(path) {
    if(path==='') { const box=document.getElementById('dashboard-data');try{box.innerHTML=dashboardHtml(await loadAdmin('overview'));}catch(e){box.innerHTML=alert(e.message+' Recarregue com Ctrl+F5 se o token antigo estiver no navegador.','error','dashboard-error');}return; }
    if(path==='inscricoes'){ const box=document.getElementById('registrations-data'); const load=async()=>{box.innerHTML=loading();try{box.innerHTML=tableRows(await loadAdmin('registrations',{page:1,filters:{}}));box.querySelectorAll('[data-registration]').forEach(b=>b.onclick=()=>{const r=(window.__rows||[]).find(x=>x.id===b.dataset.registration);if(r)openRegistration(r);});}catch(e){box.innerHTML=alert(e.message,'error','registrations-error');}}; try{const cats=await loadAdmin('categories');document.querySelector('[name="category_id"]').insertAdjacentHTML('beforeend',(cats||[]).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join(''));}catch{} await load();document.getElementById('registration-search')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);box.innerHTML=loading();try{const data=await loadAdmin('registrations',{page:1,filters:{search:fd.get('search'),category_id:document.querySelector('[name="category_id"]').value,status:document.querySelector('[name="status"]').value,type:document.querySelector('[name="type"]').value}});window.__rows=data.rows||[];box.innerHTML=tableRows(data);}catch(err){box.innerHTML=alert(err.message,'error');}});return; }
    if(path==='categorias'||path==='lotes'){const box=document.getElementById('resources-data');const cat=path==='categorias';try{const data=await loadAdmin(cat?'categories':'lots');window.__resourceData=data||[];if(cat)window.__resourceCategories=data||[];else{try{window.__resourceCategories=await loadAdmin('categories');}catch{window.__resourceCategories=[];}}box.innerHTML=resourceRows(data,cat);}catch(e){box.innerHTML=alert(e.message,'error','resources-error');}document.querySelector('[data-create-resource]')?.addEventListener('click',()=>openResource(cat,null));box.querySelectorAll('[data-edit-resource]').forEach(b=>b.onclick=()=>openResource(cat,JSON.parse(b.dataset.editResource)));return;}
    if(path==='retirada-kit'||path==='checkin'){bindOperations(path==='retirada-kit');return;}
    if(path==='relatorios'){document.querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{const out=document.getElementById('reports-message');try{const data=await loadAdmin('report',{filters:{report:b.dataset.report},page:1});downloadCSV(data.rows||[],`corrida-mpl-${b.dataset.report}.csv`);out.innerHTML=alert(`${(data.rows||[]).length} registro(s) exportados.`);}catch(e){out.innerHTML=alert(e.message,'error','reports-error');}});return;}
    if(path==='patrocinadores'){const box=document.getElementById('sponsors-data');try{const data=await loadAdmin('sponsors');box.innerHTML=sponsorRows(data);box.querySelectorAll('[data-edit-sponsor]').forEach(b=>b.onclick=()=>openSponsor(JSON.parse(b.dataset.editSponsor)));}catch(e){box.innerHTML=alert(e.message,'error');}return;}
    if(path==='colaboradores'){const box=document.getElementById('invitations-data'),msg=document.getElementById('invitations-message');let options=[];const load=async()=>{box.innerHTML=loading();try{const rows=await loadAdmin('invitations');box.innerHTML=invitationRows(rows);box.querySelectorAll('[data-copy-invite]').forEach(b=>b.onclick=async()=>{const input=b.closest('tr').querySelector('.invitation-link');try{await navigator.clipboard.writeText(input.value);}catch{input.select();document.execCommand('copy');}msg.innerHTML=alert('Link copiado.');});box.querySelectorAll('[data-send-invite]').forEach(b=>b.onclick=async()=>{const email=prompt('E-mail do colaborador:');if(!email)return;try{const r=await loadAdmin('send-invitation',{id:b.dataset.sendInvite,email});msg.innerHTML=alert(r.email_sent?'Convite enviado por e-mail.':'Convite salvo, mas o servidor não enviou o e-mail. Verifique MAIL_ENABLED.');}catch(e){msg.innerHTML=alert(e.message,'error');}});box.querySelectorAll('[data-cancel-invite]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancelar este convite? O link deixará de funcionar.'))return;try{await loadAdmin('cancel-invitation',{id:b.dataset.cancelInvite});await load();}catch(e){msg.innerHTML=alert(e.message,'error');}});box.querySelectorAll('[data-resend-invite]').forEach(b=>b.onclick=async()=>{try{const r=await loadAdmin('resend-invitation-confirmation',{id:b.dataset.resendInvite});msg.innerHTML=alert(r.email_sent?'Confirmação e QR Code reenviados.':'O servidor não enviou o e-mail. Verifique MAIL_ENABLED.');}catch(e){msg.innerHTML=alert(e.message,'error');}});}catch(e){box.innerHTML=alert(e.message,'error');}};try{options=await loadAdmin('invitation-options');}catch(e){msg.innerHTML=alert(e.message,'error');}document.querySelector('[data-create-invitation]')?.addEventListener('click',()=>openInvitation(options,load));await load();return;}
    if(path==='configuracoes'){const box=document.getElementById('settings-data');try{box.innerHTML=settingsForm(await loadAdmin('settings'));document.getElementById('settings-form').onsubmit=saveSettings;}catch(e){box.innerHTML=alert(e.message,'error','settings-error');}return;}
    if(path==='usuarios'){const box=document.getElementById('users-data');try{box.innerHTML=userRows(await loadAdmin('users'));box.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>openUser(JSON.parse(b.dataset.editUser)));}catch(e){box.innerHTML=alert(e.message,'error','users-error');}document.querySelector('[data-create-user]')?.addEventListener('click',()=>openUser(null));}
  }
  function downloadCSV(rows,filename){if(!rows.length)throw new Error('Nenhum registro para exportar.');const keys=Object.keys(rows[0]);const cell=v=>`"${String(v??'').replace(/"/g,'""')}"`;const blob=new Blob(['\ufeff'+[keys.map(cell).join(';'),...rows.map(r=>keys.map(k=>cell(r[k])).join(';'))].join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();}
  function openRegistration(r){showModal(`Inscrição #${esc(r.number)}`,`<div class="detail-heading"><h3>${esc(r.name)}</h3>${badge(r.status)}</div><dl class="detail-grid"><div><dt>CPF</dt><dd>${esc(r.cpf_masked)}</dd></div><div><dt>Categoria</dt><dd>${esc(r.category_name)}</dd></div><div><dt>Tipo</dt><dd>${badge(r.type)}</dd></div><div><dt>Valor</dt><dd>${money(r.amount_cents)}</dd></div><div><dt>Pagamento</dt><dd>${badge(r.payment_status)}</dd></div><div><dt>Camiseta</dt><dd>${esc(r.shirt_size)}</dd></div></dl><div class="detail-actions"><button class="action-link outline" data-modal-close>Fechar</button></div>`).querySelector('[data-modal-close]')?.addEventListener('click',()=>document.querySelector('.modal-backdrop')?.remove());}
  function openResource(cat,record){const fields=cat?`<div class="form-grid"><div class="form-field"><label>Nome</label><input name="name" required value="${esc(record?.name||'')}"></div><div class="form-field"><label>Distância (km)</label><input name="distance_km" type="number" required value="${esc(record?.distance_km||5)}"></div><div class="form-field"><label>Quantidade de vagas</label><input name="capacity" type="number" required value="${esc(record?.capacity||100)}"></div><div class="form-field"><label>Idade mínima</label><input name="min_age" type="number" required value="${esc(record?.min_age||18)}"></div><div class="form-field"><label>Idade máxima</label><input name="max_age" type="number" required value="${esc(record?.max_age||100)}"></div></div>`:`<div class="form-grid"><div class="form-field"><label>Nome</label><input name="name" required value="${esc(record?.name||'')}"></div><div class="form-field"><label>Categoria</label><select name="category_id" required><option value="">Selecione</option>${(window.__resourceCategories||[]).map(c=>`<option value="${c.id}" ${String(c.id)===String(record?.category_id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="form-field"><label>Preço em centavos</label><input name="price_cents" type="number" required value="${esc(record?.price_cents||0)}"></div><div class="form-field"><label>Quantidade de vagas</label><input name="capacity" type="number" required value="${esc(record?.capacity||100)}"></div><div class="form-field"><label>Início</label><input name="starts_at" type="datetime-local" required value="${esc((record?.starts_at||'').slice(0,16))}"></div><div class="form-field"><label>Fim</label><input name="ends_at" type="datetime-local" required value="${esc((record?.ends_at||'').slice(0,16))}"></div></div>`;const m=showModal(`${record?'Editar':'Criar'} ${cat?'categoria':'lote'}`,`<form id="resource-form">${fields}<label class="checkbox-label"><input type="checkbox" name="active" ${record?.active?'checked':''}>Ativo</label><button class="primary-button">Salvar alterações</button><div id="resource-message"></div></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target).entries());data.active=e.target.active.checked;try{await loadAdmin(cat?'save-category':'save-lot',{...(record?.id?{id:record.id}:{}),data});m.remove();navigate(location.pathname);}catch(err){m.querySelector('#resource-message').innerHTML=alert(err.message,'error');}};}
  function bindOperations(kit){let method='CPF',scanner=null;const result=document.getElementById('operation-result');const renderRecord=r=>{result.innerHTML=`<div><div class="result-title">${icon(kit?'shirt':'scan')}<span>PARTICIPANTE LOCALIZADO</span></div><h2>${esc(r.name)}</h2><p>#${esc(r.number)} · ${esc(r.cpf_masked)}</p><dl class="detail-grid"><div><dt>Categoria</dt><dd>${esc(r.category_name)}</dd></div><div><dt>Camiseta</dt><dd>${esc(r.shirt_size)}</dd></div><div><dt>Tipo</dt><dd>${badge(r.type)}</dd></div><div><dt>Pagamento</dt><dd>${badge(r.payment_status)}</dd></div><div><dt>Kit</dt><dd>${r.kit_at?'Já retirado':'Não retirado'}</dd></div><div><dt>Check-in</dt><dd>${r.checkin_at?'Já realizado':'Não realizado'}</dd></div></dl><button class="primary-button" id="operation-confirm" ${r.status!=='CONFIRMED'||(kit?r.kit_at:r.checkin_at)?'disabled':''}>${kit?'Confirmar retirada do kit':'Confirmar check-in'}${icon('check',18)}</button></div>`;document.getElementById('operation-confirm').onclick=async()=>{try{await invoke(kit?'withdraw-kit':'checkin',{event_id:member.event_id,registration_id:r.id});result.innerHTML=`<div class="operation-success"><span>${icon('check',58)}</span><h2>Pronto para o próximo!</h2><p>${kit?'Retirada do kit confirmada':'Check-in confirmado'} , ${esc(r.name)}</p><button class="action-link outline" data-next>Próximo participante</button></div>`;result.querySelector('[data-next]').onclick=()=>location.reload();}catch(e){result.insertAdjacentHTML('afterbegin',alert(e.message,'error','operation-error'));}};};const search=async()=>{const q=document.querySelector('#operation-search [name="query"]').value.trim();if(!q)return;result.innerHTML=loading();try{renderRecord(await invoke('validate-ticket',{event_id:member.event_id,method,query:q}));}catch(e){result.innerHTML=alert(e.message,'error','operation-error');}};document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{method=b.dataset.method;document.querySelectorAll('[data-method]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#operation-search [name="query"]').placeholder=method==='CPF'?'000.000.000-00':method==='QR'?'Cole o token do QR Code':'Número da inscrição';});document.getElementById('operation-search').onsubmit=e=>{e.preventDefault();search();};document.querySelector('[data-toggle-camera]').onclick=async()=>{const v=document.getElementById('scanner-viewport');if(scanner){try{await scanner.stop();}catch{}scanner=null;v.innerHTML='<div class="scanner-idle"><div class="scan-corners">'+icon('scan',35)+'</div><p>Aponte para o QR Code do participante</p></div>';return;}if(!window.Html5Qrcode){document.getElementById('camera-error').innerHTML=alert('Scanner não carregado. Use a busca manual.','error');return;}v.innerHTML='';try{scanner=new Html5Qrcode('scanner-viewport');await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:220,height:220}},async text=>{await scanner.stop();scanner=null;document.querySelector('#operation-search [name="query"]').value=text;method='QR';search();},()=>{});}catch{document.getElementById('camera-error').innerHTML=alert('Não foi possível abrir a câmera. Verifique a permissão e o HTTPS ou use a busca manual.','error','camera-error');scanner=null;}};}
  async function saveSettings(e){e.preventDefault();const form=e.target,msg=document.getElementById('settings-message');const data=Object.fromEntries(new FormData(form).entries());data.published=form.published.checked;data.registration_open=form.registration_open.checked;try{await loadAdmin('save-settings',{data});msg.innerHTML=alert('Configurações salvas.');}catch(err){msg.innerHTML=alert(err.message,'error','settings-save-error');}}
  function openUser(record){const m=showModal('Permissão administrativa',`<form id="user-form">${alert('Cadastre o usuário administrativo no MariaDB. Senhas são armazenadas com hash seguro.','','user-auth-info')}<label>Nome</label><input name="name" required value="${esc(record?.name||'')}"><label>E-mail do usuário</label><input name="email" type="email" required ${record?'readonly':''} value="${esc(record?.email||'')}"><label>Senha inicial</label><input name="password" type="password" ${record?'':'required'}><label>Perfil</label><select name="role"><option>SUPER_ADMIN</option><option>ADMIN</option><option>FINANCEIRO</option><option>OPERADOR</option><option>CONSULTA</option></select><label class="checkbox-label"><input type="checkbox" name="active" ${record?.active!==false?'checked':''}>Acesso ativo</label><button class="primary-button">Salvar acesso</button><div id="user-message"></div></form>`);m.querySelector('[name="role"]').value=record?.role||'CONSULTA';m.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target).entries());data.active=e.target.active.checked;try{await loadAdmin('save-user',{id:record?.id||0,data});m.remove();navigate('/admin/usuarios');}catch(err){m.querySelector('#user-message').innerHTML=alert(err.message,'error');}};}
  async function loginSubmit(form){const email=form.email.value.trim(),password=form.password.value;const msg=document.getElementById('login-message');if(!/^\S+@\S+\.\S+$/.test(email)||!password){msg.innerHTML=alert('Informe e-mail e senha.','error','admin-login-error');return;}try{const r=await invoke('auth-login',{email,password});sessionStorage.setItem('mpl_token',r.token);session={access_token:r.token,user:r.user};member={role:String(r.user.role||'').toUpperCase(),event_id:null,event_name:event.name};await navigate(BASE+'/admin');}catch(e){msg.innerHTML=alert(e.message,'error','admin-login-error');}}
  function bindLogin(){const f=document.getElementById('login-form');if(!f)return;f.addEventListener('submit',e=>{e.preventDefault();loginSubmit(f);});}
  async function logout(){try{if(sessionStorage.getItem('mpl_participant_token'))await invoke('participant-logout');}catch(ignored){}sessionStorage.removeItem('mpl_token');sessionStorage.removeItem('mpl_participant_token');sessionStorage.removeItem('mpl_participant_email');localStorage.removeItem('mpl_token');localStorage.removeItem('mpl_email');session=null;member=null;navigate('/');}
  function bindPassword(){return;}
  async function navigate(to){const target=String(to||'/');const appTarget=BASE&&target.startsWith('/')&&!target.startsWith(BASE+'/')&&target!==BASE?BASE+target:target;const u=new URL(appTarget,location.origin);history.pushState({},'',u.pathname+u.search+u.hash);await renderRoute();if(u.hash)setTimeout(()=>document.getElementById(u.hash.slice(1))?.scrollIntoView({behavior:'smooth'}),80);}
  async function loadRouteInvitation(path){if(path!=='/inscricao')return;const token=new URLSearchParams(location.search).get('convite');if(!token){activeInvitation=null;return;}if(activeInvitation?._token===token)return;try{activeInvitation=await invoke('invitation-info',{token});activeInvitation._token=token;}catch(e){activeInvitation={error:e.message,_token:token};}}
  async function renderRoute(){let path=location.pathname; if(BASE && path.startsWith(BASE)){path=path.slice(BASE.length)||'/';} path=path.replace(/\/$/,'')||'/'; await loadRouteInvitation(path); if(path.startsWith('/admin')&&path!=='/admin/login'&&!member){setView(publicShell(`<div class="container inner-page">${heading('Área administrativa','ACESSO RESTRITO','Faça login para continuar.')}${loginForm()}</div>`));bindLogin();return;} if(path==='/admin/login'){setView(publicShell(loginPage()));bindLogin();return;} if(path.startsWith('/admin')){const sub=path.replace('/admin','').replace(/^\//,'');if(!canOpenAdmin(sub)){setView(adminShell(`<div class="container inner-page">${alert('Você não tem permissão para acessar esta área.','error')}</div>`,sub));return;}let html='';if(sub==='')html=dashboard();else if(['inscricoes','colaboradores','categorias','lotes','retirada-kit','checkin','relatorios','configuracoes','patrocinadores','usuarios'].includes(sub))html=sub==='inscricoes'?registrations():sub==='colaboradores'?collaboratorsAdmin():['categorias','lotes'].includes(sub)?resources(sub):sub==='retirada-kit'?operations(true):sub==='checkin'?operations(false):sub==='relatorios'?reports():sub==='configuracoes'?settings():sub==='patrocinadores'?sponsorsAdmin():users();setView(adminShell(html,sub));await bindAdminPage(sub);return;} let html;switch(path){case '/':html=home();break;case '/inscricao':html=registration();break;case '/consultar-inscricao':html=accessPage();break;case '/minha-inscricao':html=participant();break;case '/pagamento':case '/pagamento/sucesso':html=payment();break;case '/regulamento':case '/privacidade':html=legal();break;case '/patrocinio':html=sponsorship();break;case '/auth/atualizar-senha':html=updatePassword();break;default:html=`<div class="container inner-page">${heading('Esse percurso não existe.')}<a href="${BASE}/" class="text-link">Voltar para o início</a></div>`;}setView(publicShell(html));bindRegistration();bindEmailForm();bindSponsorForm();bindPassword();if(path==='/minha-inscricao')renderParticipantData();if(path.startsWith('/pagamento'))renderPayment();}
  window.addEventListener('popstate',renderRoute);
  (async()=>{await loadEvent();await loadPublicSponsors();await loadAuth();await renderRoute();})();
